from collections import deque

class Solution:
    def maxDepth(self, root: 'Node') -> int:
        queue = deque([root] if root else [])
        depth = 0
        while queue:
            for _ in range(len(queue)):
                queue.extend(queue.popleft().children)
            depth += 1
        return depth
